const items = $input.all();

return items.map(item => {
  const data = item.json;

  const prixSysteme = data.PRI_0;
  const prixDevis = data.tarif_devis;

  let ecart_montant = null;
  let ecart_pourcentage = null;

  if (prixSysteme !== null && prixSysteme !== undefined && prixSysteme !== 0) {
    ecart_montant = prixDevis - prixSysteme;
    ecart_pourcentage = (ecart_montant / prixSysteme) * 100;
  }

  return {
    json: {
      ...data,
      ecart_montant: ecart_montant !== null ? Math.round(ecart_montant * 100) / 100 : null,
      ecart_pourcentage: ecart_pourcentage !== null ? Math.round(ecart_pourcentage * 100) / 100 : null
    }
  };
});

// ── Mode : "Run Once for All Items" ──
// Regroupe les articles par fournisseur (numero_rfpn) et génère
// UN SEUL email de négociation tarifaire par fournisseur,
// listant tous les articles concernés dans un tableau.

const items = $input.all().map(i => i.json);

// ─────────────────────────────────────────────
// Regroupement par numero_rfpn (= même envoi/fournisseur)
// ─────────────────────────────────────────────
const groups = {};

for (const it of items) {
  const key = it.numero_rfpn || it.code_fournisseur || 'INCONNU';
  if (!groups[key]) {
    groups[key] = {
      numero_rfpn: it.numero_rfpn,
      rfq_number: it.number_rfq,
      code_fournisseur: it.BPANUM_0,
      nom_fournisseur: it.BPRNAM_0,
      email_fournisseur: it.WEB_0,
      articles: []
    };
  }
  groups[key].articles.push({
    code_article: it.code_article,
    designation_article: it.designation_article,
    prix_unitaire: it.tarif_devis,
    prix_unitaire_sys: it.PRI_0,
    quantite_disponible: it.quantite_disponible || 1,
    ecart_montant: it.ecart_montant,
    ecart_pourcentage: it.ecart_pourcentage
  });
}

// ─────────────────────────────────────────────
// Génération d'un email par fournisseur
// ─────────────────────────────────────────────
const result = Object.values(groups).map(g => {

  // Construction des lignes du tableau (une par article)
  let lignesArticlesHtml = '';
  for (const a of g.articles) {
    lignesArticlesHtml += `
      <tr>
        <td style="padding: 10px; border: 1px solid #e5e7eb;">${a.code_article}</td>
        <td style="padding: 10px; border: 1px solid #e5e7eb;">${a.designation_article}</td>
        <td style="padding: 10px; border: 1px solid #e5e7eb; text-align: center;">${a.quantite_disponible}</td>
        <td style="padding: 10px; border: 1px solid #e5e7eb; color: #dc2626; font-weight: 600; text-align: right;">${a.prix_unitaire} MAD</td>
        <td style="padding: 10px; border: 1px solid #e5e7eb; color: #059669; font-weight: 600; text-align: right;">${a.prix_unitaire_sys} MAD</td>
        <td style="padding: 10px; border: 1px solid #e5e7eb; text-align: right;">+${a.ecart_montant} MAD (+${a.ecart_pourcentage}%)</td>
      </tr>`;
  }

  const nbArticles = g.articles.length;

  // ─────────────────────────────────────────────
  // Corps HTML de l'email
  // ─────────────────────────────────────────────
  const email_html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
</head>
<body style="font-family: Arial, sans-serif; color: #1f2937; max-width: 700px; margin: 0 auto;">

  <div style="background: #2d5a87; padding: 20px; border-radius: 8px 8px 0 0;">
    <h2 style="color: white; margin: 0;">Demande de révision tarifaire</h2>
    <p style="color: #dbeafe; margin: 5px 0 0;">Référence: ${g.numero_rfpn}</p>
  </div>

  <div style="padding: 24px; border: 1px solid #e5e7eb; border-top: none;">
    <p>Bonjour ${g.nom_fournisseur},</p>

    <p>
      Nous avons bien reçu votre offre de prix suite à notre demande de cotation
      <strong>${g.rfq_number}</strong>. Après comparaison avec nos tarifs de référence,
      nous constatons un écart significatif sur ${nbArticles} article(s) :
    </p>

    <table style="width: 100%; border-collapse: collapse; margin: 20px 0; font-size: 13px;">
      <thead>
        <tr style="background: #333; color: #fff;">
          <th style="padding: 8px; border: 1px solid #ddd; text-align: left;">Code Article</th>
          <th style="padding: 8px; border: 1px solid #ddd; text-align: left;">Désignation</th>
          <th style="padding: 8px; border: 1px solid #ddd; text-align: center;">Qté</th>
          <th style="padding: 8px; border: 1px solid #ddd; text-align: right;">Votre prix</th>
          <th style="padding: 8px; border: 1px solid #ddd; text-align: right;">Prix référence</th>
          <th style="padding: 8px; border: 1px solid #ddd; text-align: right;">Écart</th>
        </tr>
      </thead>
      <tbody>
        ${lignesArticlesHtml}
      </tbody>
    </table>

    <p>
      Afin de poursuivre notre collaboration, nous vous invitons à revoir votre proposition
      tarifaire sur ces articles et à nous transmettre des prix plus proches de notre référence
      interne, si possible.
    </p>

    <p>
      Merci de bien vouloir nous faire part de votre nouvelle proposition en réponse à cet email,
      en conservant la référence <strong>${g.numero_rfpn}</strong> dans l'objet.
    </p>

    <p style="margin-top: 30px;">
      Cordialement,<br>
      Service Achats
    </p>
  </div>

  <div style="background: #f9fafb; padding: 12px 24px; border-radius: 0 0 8px 8px; font-size: 12px; color: #9ca3af;">
    Référence RFQ initiale: ${g.rfq_number} | Référence RFPN: ${g.numero_rfpn}
  </div>

</body>
</html>
`;

  // ─────────────────────────────────────────────
  // Retour
  // ─────────────────────────────────────────────
  return {
    json: {
      numero_rfpn: g.numero_rfpn,
      rfq_number: g.rfq_number,
      code_fournisseur: g.code_fournisseur,
      nom_fournisseur: g.nom_fournisseur,
      email_fournisseur: g.email_fournisseur,
      nombre_articles: nbArticles,
      articles: g.articles,
      email_html: email_html,
      email_subject: `Demande de révision tarifaire ${g.numero_rfpn} - ${nbArticles} article(s)`,
      date_envoi: new Date().toISOString()
    }
  };
});

return result;

const crypto = require('crypto');

const items = $input.all().map(i => i.json);
const data = $('If1').all().map(i => i.json);

const now = new Date();
const annee = now.getFullYear();
const mois = String(now.getMonth() + 1).padStart(2, '0');
const jour = String(now.getDate()).padStart(2, '0');
const heure = String(now.getHours()).padStart(2, '0');
const minute = String(now.getMinutes()).padStart(2, '0');
const seconde = String(now.getSeconds()).padStart(2, '0');
const uuid = crypto.randomUUID();
const shortUuid = uuid.substring(0, 4).toUpperCase();
const numero_rfpn = `RFPN-${annee}-${mois}${jour}${heure}${minute}${seconde}-${shortUuid}`;

const result = items.map(article => {
  const d = data.find(t => t.PLICRI1_0 === article.code_article);
  return {
    json: {
      ...article,
      ...(d || {}),
      numero_rfpn: numero_rfpn
    }
  };
});

return result;
